j:jelly.script:
var sectionsToHide = {
   'Activities'        : '31e7470137232100b2cf04368e41f1a1',
   'Application'       : 'a655ee20ff033100f03bffffffffffcb',
   'Inputs'            : 'b377470137232100b2cf04368e41f192',
   'Schedule'          : 'b0b7470137232100b2cf04368e41f19e',
   'Estimated Runtime' : '55a9f34137003100b2cf04368e41f11b'
}

setTimeout(
    function() {
        for (var key in sectionsToHide) {
            var id = sectionsToHide[key];
            if ( !$j("#section-" + id).is(".state-closed") )
	            hideReveal(id);
        }
    }, 
    100
);
